      SUBROUTINE MRETCC     STORES VALUES OF RC2 AT BEGINNING OF FITTED SECTIONCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'R.CIN'      INCLUDE 'RC.CIN'      INCLUDE 'RCP.CIN'      INCLUDE 'RCPS.CIN'      INCLUDE 'RCS.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'RC2S.CIN'      INCLUDE 'RSS.CIN'      INCLUDE 'R0P.CIN'      INCLUDE 'R0PS.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'R2PS.CIN'      INCLUDE 'T.CIN'      INCLUDE 'TC2.CIN'      INCLUDE 'TC2S.CIN'      INCLUDE 'TSS.CIN'      INCLUDE 'UC2.CIN'      INCLUDE 'UC2S.CIN'CC-------------------------------------------------------------------      R0PS = R0P      DO 10 J = 1, 36      RSSL(J) = RL(J)      RCSL(J) = RCL(J)   10 RC2SL(J) = RC2L(J)      RCPS = RCP      R2PS = R2P      IF (NORD1 .GE. 2) THEN      DO 20 J = 1, 105        TSSL(J) = TL(J)   20   TC2SL(J) = TC2L(J)      ENDIF      IF (NORD1 .GE. 3) THEN        DO 30 J = 1, 280   30   UC2SL(J) = UC2L(J)      ENDIF      RETURN      END